__all__ = ["parse", "JsonError"]


class JsonError(ValueError):
    """Raised on malformed JSON input.

    Attributes:
        msg:  Description of the error.
        line: 1-based line number where the error occurred.
        col:  1-based column number where the error occurred.
    """

    def __init__(self, msg, line, col):
        super().__init__(f"{msg} at line {line} column {col}")
        self.msg = msg
        self.line = line
        self.col = col


_ESCAPES = {
    '"': '"',
    "\\": "\\",
    "/": "/",
    "b": "\b",
    "f": "\f",
    "n": "\n",
    "r": "\r",
    "t": "\t",
}

_WS = " \t\n\r"

_NUMBER_RE = None  # compiled lazily below
import re  # noqa: E402  (re is fine; only `json` is forbidden)

_NUMBER_RE = re.compile(
    r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?"
)


class _Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.n = len(text)

    # -- helpers ---------------------------------------------------------

    def error(self, msg):
        line = self.text.count("\n", 0, self.pos) + 1
        last_nl = self.text.rfind("\n", 0, self.pos)
        col = self.pos - last_nl  # works when no newline found too (rfind=-1)
        return JsonError(msg, line, col)

    def skip_ws(self):
        while self.pos < self.n and self.text[self.pos] in _WS:
            self.pos += 1

    def peek(self):
        return self.text[self.pos] if self.pos < self.n else ""

    def expect(self, ch):
        if self.peek() != ch:
            raise self.error(f"expected {ch!r}")
        self.pos += 1

    # -- grammar ---------------------------------------------------------

    def parse_value(self):
        self.skip_ws()
        if self.pos >= self.n:
            raise self.error("unexpected end of input")
        ch = self.text[self.pos]
        if ch == "{":
            return self.parse_object()
        if ch == "[":
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch in "-0123456789":
            return self.parse_number()
        if self.text.startswith("true", self.pos):
            self.pos += 4
            return True
        if self.text.startswith("false", self.pos):
            self.pos += 5
            return False
        if self.text.startswith("null", self.pos):
            self.pos += 4
            return None
        raise self.error(f"unexpected character {ch!r}")

    def parse_object(self):
        obj = {}
        self.expect("{")
        self.skip_ws()
        if self.peek() == "}":
            self.pos += 1
            return obj
        while True:
            self.skip_ws()
            if self.peek() != '"':
                raise self.error("expected string key")
            key = self.parse_string()
            self.skip_ws()
            if self.peek() != ":":
                raise self.error("expected ':'")
            self.pos += 1
            obj[key] = self.parse_value()
            self.skip_ws()
            ch = self.peek()
            if ch == ",":
                self.pos += 1
            elif ch == "}":
                self.pos += 1
                return obj
            else:
                raise self.error("expected ',' or '}'")

    def parse_array(self):
        arr = []
        self.expect("[")
        self.skip_ws()
        if self.peek() == "]":
            self.pos += 1
            return arr
        while True:
            arr.append(self.parse_value())
            self.skip_ws()
            ch = self.peek()
            if ch == ",":
                self.pos += 1
            elif ch == "]":
                self.pos += 1
                return arr
            else:
                raise self.error("expected ',' or ']'")

    def parse_string(self):
        self.expect('"')
        chunks = []
        while True:
            if self.pos >= self.n:
                raise self.error("unterminated string")
            ch = self.text[self.pos]
            if ch == '"':
                self.pos += 1
                break
            if ch == "\\":
                self.pos += 1
                if self.pos >= self.n:
                    raise self.error("unterminated escape sequence")
                esc = self.text[self.pos]
                if esc in _ESCAPES:
                    chunks.append(_ESCAPES[esc])
                    self.pos += 1
                elif esc == "u":
                    cp = self._parse_u()
                    if 0xD800 <= cp <= 0xDBFF:
                        # High surrogate: require a following \uDC00-\uDFFF.
                        if (
                            self.pos + 2 < self.n
                            and self.text[self.pos + 1] == "\\"
                            and self.text[self.pos + 2] == "u"
                        ):
                            save = self.pos
                            self.pos += 2
                            low = self._parse_u()
                            if 0xDC00 <= low <= 0xDFFF:
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (
                                    low - 0xDC00
                                )
                            else:
                                self.pos = save + 1
                                raise self.error(
                                    "invalid low surrogate in surrogate pair"
                                )
                        else:
                            raise self.error("lone high surrogate")
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise self.error("lone low surrogate")
                    chunks.append(chr(cp))
                else:
                    raise self.error(f"invalid escape sequence \\{esc}")
            elif ord(ch) < 0x20:
                raise self.error(f"unescaped control character U+{ord(ch):04X}")
            else:
                chunks.append(ch)
                self.pos += 1
        return "".join(chunks)

    def _parse_u(self):
        """Parse exactly four hex digits after '\\u'; cursor sits after 'u'."""
        hexdigits = self.text[self.pos + 1 : self.pos + 5]
        if len(hexdigits) != 4 or any(c not in "0123456789abcdefABCDEF" for c in hexdigits):
            raise self.error("invalid \\uXXXX escape")
        self.pos += 5
        return int(hexdigits, 16)

    def parse_number(self):
        m = _NUMBER_RE.match(self.text, self.pos)
        if not m:
            raise self.error("invalid number")
        start = self.pos
        end = m.end()
        # Guard against things like "01" or "1." or "1.e5"
        raw = self.text[start:end]
        self.pos = end
        if self.peek() in ".eE0123456789+-" and not _is_number_boundary(
            self.peek()
        ):
            pass  # boundary chars handled by regex; extra digits caught below
        # Ensure number is not immediately followed by an identifier char.
        nxt = self.peek()
        if nxt.isalpha() or nxt in "_.":
            raise self.error("invalid number")
        if "." in raw or "e" in raw or "E" in raw:
            return float(raw)
        return int(raw)


def _is_number_boundary(ch):
    return ch in "" ",]}"


def parse(text):
    """Parse a JSON document string into Python objects."""
    p = _Parser(text)
    value = p.parse_value()
    p.skip_ws()
    if p.pos != p.n:
        raise p.error("trailing data after JSON value")
    return value
