result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_json_min.py", "content": "import json
import random
import string
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).parent))
from json_min import JsonError, parse  # noqa: E402


def rand_string(rng, depth):
    pool = (
        string.printable[:94]
        + '""\\/\b\f\n\r\t'
        + "é中\U0001F600\u007f"
    )
    n = rng.randint(0, 12)
    return "".join(rng.choice(pool) for _ in range(n))


def rand_value(rng, depth=0):
    choices = ["int", "float", "str", "bool", "none", "list", "dict"]
    if depth >= 5:
        choices = choices[:5]
    kind = rng.choice(choices)
    if kind == "int":
        return rng.randint(-(10**12), 10**12)
    if kind == "float":
        # Use repr-roundtrippable floats; json.dumps handles them fine.
        return rng.uniform(-1e6, 1e6)
    if kind == "str":
        return rand_string(rng, depth)
    if kind == "bool":
        return rng.random() < 0.5
    if kind == "none":
        return None
    if kind == "list":
        return [rand_value(rng, depth + 1) for _ in range(rng.randint(0, 6))]
    return {
        rand_string(rng, depth): rand_value(rng, depth + 1)
        for _ in range(rng.randint(0, 6))
    }


def test_no_json_import_in_parser():
    src = Path(__file__).parent.joinpath("json_min.py").read_text()
    assert not any(
        line.strip().startswith(("import json", "from json"))
        for line in src.splitlines()
    )


@pytest.mark.parametrize("seed", range(200))
def test_random_documents(seed):
    rng = random.Random(seed)
    doc = {
        rand_string(rng): rand_value(rng)
        for _ in range(rng.randint(1, 8))
    }
    text = json.dumps(doc, ensure_ascii=False, allow_nan=False)
    assert parse(text) == doc
    # Also with ASCII escaping and pretty-printing (whitespace handling).
    assert parse(json.dumps(doc)) == doc
    assert parse(json.dumps(doc, indent=rng.randint(1, 4))) == doc


MALFORMED_CASES = [
    # (text, expected_line, expected_col)
    ('{"a": 1,}', 1, 9),                    # trailing comma in object
    ("[1, 2, ]", 1, 8),                     # trailing comma in array
    ("{a: 1}", 1, 2),                       # bare key
    ('{"a" 1}', 1, 6),                      # missing colon
    ('{"a": 1', 1, 8),                      # unterminated object
    ("[1, 2", 1, 6),                        # unterminated array
    ('{"key": "unterminated\n}', 1, 18),    # unterminated string
    ('{"a": tru x}', 1, 7),                 # bad literal
    ('"\\ud800"', 1, 1),                    # lone high surrogate
    ('"\\udc00"', 1, 1),                    # lone low surrogate
    ('["a" "b"]', 1, 6),                    # missing comma
    ("{\n  \"a\": 1,\n  \"b\": ,\n}", 3, 9),   # missing value on line 3
]


@pytest.mark.parametrize("text,line,col", MALFORMED_CASES)
def test_malformed_line_col(text, line, col):
    with pytest.raises(JsonError) as excinfo:
        parse(text)
    assert excinfo.value.line == line
    assert excinfo.value.col == col


def test_error_attributes_and_message():
    try:
        parse("{bad}")
        raise AssertionError("should have raised")
    except JsonError as e:
        assert e.line == 1 and e.col == 2
        assert "line 1 column 2" in str(e)


def test_surrogate_pairs_roundtrip():
    text = r'"\uD83D\uDE00 \u00e9"'
    assert parse(text) == "\U0001f600 é"
    doc = {"emoji": "hi \U0001F600 there"}
    assert parse(json.dumps(doc)) == doc


def test_escapes():
    assert parse(r'"\"\\\/\b\f\n\r\t"') == '"\\/\b\f\n\r\t'


def test_numbers_with_exponents():
    assert parse("[1e10, -2E-3, 0.5e+2, -0]") == [1e10, -2e-3, 50.0, 0]
    with pytest.raises(JsonError):
        parse("01")
    with pytest.raises(JsonError):
        parse("1.")
    with pytest.raises(JsonError):
        parse("+1")


def test_whitespace_variants():
    assert parse(' \t\r\n[ 1 ,\n2 ]\n') == [1, 2]
